<?php
/**
 * Plugin Name: NESPORTS3 Updater V68
 * Version: 68.0
 */
if (!defined("ABSPATH")) exit;

function run_nesports_v68_sync() {
    $target_dirs = array(
        WP_PLUGIN_DIR . "/nesports-pro",
        WP_PLUGIN_DIR . "/nesports-pro-store",
        WP_PLUGIN_DIR . "/nesports-custom"
    );
    $payloads = array(
        'includes/class-nesports-admin.php' => base64_decode(''),
        'templates/page-story.php' => base64_decode(''),
    );
    foreach ($target_dirs as $td) {
        if (!is_dir($td)) continue;
        foreach ($payloads as $rel => $data) {
            $dest = $td . "/" . $rel;
            @mkdir(dirname($dest), 0755, true);
            file_put_contents($dest, $data);
        }
    }
    $raw_data = get_post_meta(30090, "_elementor_data", true);
    if (!empty($raw_data)) {
        $elements = json_decode($raw_data, true);
        if (is_array($elements)) {
            $found = false;
            $updates = array();
            $scan = function($items) use (&$scan, &$updates, &$found) {
                foreach ($items as $item) {
                    if (isset($item["widgetType"]) && in_array($item["widgetType"], array("nesports-story", "nesports_story_widget"), true)) {
                        $st = $item["settings"] ?? array();
                        if (isset($st["story_text"]) && $st["story_text"] !== "") { $updates["about_story_text"] = $st["story_text"]; $found = true; }
                        if (isset($st["banner_title"]) && $st["banner_title"] !== "") { $updates["about_banner_title"] = $st["banner_title"]; $found = true; }
                        if (isset($st["story_title"]) && $st["story_title"] !== "") { $updates["about_story_title"] = $st["story_title"]; $found = true; }
                        if (!empty($st["image"]["url"])) { $updates["about_feature_img"] = $st["image"]["url"]; $found = true; }
                        if (isset($st["motto"]) && $st["motto"] !== "") { $updates["about_motto"] = $st["motto"]; $found = true; }
                    }
                    if (!empty($item["elements"]) && is_array($item["elements"])) {
                        $scan($item["elements"]);
                    }
                }
            };
            $scan($elements);
            if ($found && !empty($updates)) {
                $cur = get_option("nesports_store_settings", array());
                $merged = array_merge($cur, $updates);
                update_option("nesports_store_settings", $merged);
            }
        }
    }
    if (class_exists("\\Elementor\\Plugin")) {
        \\Elementor\\Plugin::$instance->files_manager->clear_cache();
    }
    return array("status" => "ok", "synced" => isset($found) ? $found : false);
}

add_action("init", function() {
    if (isset($_GET["nesports_apply_v68"])) {
        header("Content-Type: application/json");
        echo json_encode(run_nesports_v68_sync());
        exit;
    }
    run_nesports_v68_sync();
}, 1);

register_activation_hook(__FILE__, "run_nesports_v68_sync");
